import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.BZzouRtU.js";const d="/study/images/browser/audio-flyby-trajectory.svg",i="/study/images/browser/audio-flyby-curves.svg",b=JSON.parse('{"title":"Web Audioで音源の通過音を作る","description":"","frontmatter":{"title":"Web Audioで音源の通過音を作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"聞き手の前を音源が通過するとき、軌道から位置、距離、聞き手に向かう速度を求め、音の左右の位置と大きさ、高さを変える。","aliases":["Web Audio API","通過音","フライバイ","flyby","ドップラー効果","視線方向の速度","距離減衰","PannerNode","AudioBufferSourceNode","playbackRate","setValueCurveAtTime"],"verification":"OpenStaxの移動音源の式とW3C Web Audio APIの再生速度、パンニング、距離モデルの仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-flyby.md","filePath":"browser/audio-flyby.md"}'),s={name:"browser/audio-flyby.md"};function l(n,e,c,u,h,g){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="web-audioで音源の通過音を作る" tabindex="-1">Web Audioで音源の通過音を作る <a class="header-anchor" href="#web-audioで音源の通過音を作る" aria-label="Permalink to &quot;Web Audioで音源の通過音を作る&quot;">​</a></h1><p>車が左から右へ通過するとき、接近中は左寄りで高く聞こえ、正面を通るときに音が大きくなり、遠ざかると右寄りで低く聞こえます。音源の軌道を一つ決めると、同じ時刻の位置から左右の配分と距離による減衰を、聞き手に向かう速度から音の高さを求められます。<a href="/study/browser/audio-spatial-panning.html">音の定位と距離減衰</a> · <a href="/study/browser/audio-doppler.html">ドップラー効果</a></p><h2 id="音源の位置と聞き手までの距離" tabindex="-1">音源の位置と聞き手までの距離 <a class="header-anchor" href="#音源の位置と聞き手までの距離" aria-label="Permalink to &quot;音源の位置と聞き手までの距離&quot;">​</a></h2><p>聞き手は原点に止まり、前方の <code>−Z</code> を向きます。音源は聞き手の <code>b</code> メートル前にある直線を、速度 <code>v</code> で左から右へ進みます。正面を通る時刻を <code>t = 0</code> とすると、音源の位置は <code>(x, y, z) = (v × t, 0, −b)</code> です。聞き手と音源の距離 <code>d</code> は、この位置を直角三角形の斜辺として求められます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = v × t</span></span>
<span class="line"><span>d = √(x² + b²)</span></span></code></pre></div><figure class="study-figure"><img src="`+d+'" alt="聞き手を原点に置き、音源が前方10 mの直線を左から右へ進む。40 m/sの例では、時刻マイナス0.5秒で左20 m、0秒で正面、プラス0.5秒で右20 mにあり、正面が最も近い。" width="760" height="416" loading="lazy"><figcaption>同じ速度で進んでいても、音源と聞き手を結ぶ線の向きと長さは時刻によって変わります。<a href="/study/images/browser/audio-flyby-trajectory.svg" target="_blank" rel="noopener noreferrer">音源の軌道を拡大</a></figcaption></figure><h2 id="速度を聞き手の方向に投影する" tabindex="-1">速度を聞き手の方向に投影する <a class="header-anchor" href="#速度を聞き手の方向に投影する" aria-label="Permalink to &quot;速度を聞き手の方向に投影する&quot;">​</a></h2><p>この例では、音源の速度ベクトルは <code>(v, 0, 0)</code>、音源から聞き手を向く単位ベクトルは <code>(−x / d, 0, b / d)</code> です。両者の内積 <code>u = −v × x / d</code> が、聞き手に向かう速度です。接近中は <code>u &gt; 0</code>、正面では速度と聞き手の方向が直交するので <code>u = 0</code>、通過後は <code>u &lt; 0</code> になります。音源の速さ <code>v</code> は全区間で一定です。<a href="https://openstax.org/books/physics/pages/14-3-doppler-effect-and-sonic-booms" target="_blank" rel="noreferrer">OpenStaxの音源の速度成分とドップラー効果</a></p><p>音速を343 m/s、元の音を440 Hzとすると、再生速度の倍率は <code>343 / (343 − u)</code>、その時刻の予測周波数は <code>440 × 343 / (343 − u)</code> です。この例ではゲーム内の現在位置を使って高さを計算します。物理的な到達時刻まで求める場合は、音を出した位置から聞き手までの伝播時間も加わります。<a href="/study/browser/audio-doppler.html">ドップラー効果</a> · <a href="https://www.w3.org/TR/webaudio/#AudioBufferSourceNode" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioBufferSourceNode</a></p><h2 id="位置で左右と音量を変える" tabindex="-1">位置で左右と音量を変える <a class="header-anchor" href="#位置で左右と音量を変える" aria-label="Permalink to &quot;位置で左右と音量を変える&quot;">​</a></h2><p>音源の位置を <code>PannerNode</code> に渡すと、モノラル音を聞き手から見た方向に応じて左右に配分できます。実践は <code>panningModel = &quot;equalpower&quot;</code> を使い、音源が正面を通る瞬間の左右の振幅は等しくなります。距離によるゲインには <code>distanceModel = &quot;inverse&quot;</code>、<code>refDistance = 5</code>、<code>rolloffFactor = 1</code> を使います。この例では常に <code>d ≥ 5</code> なので、距離ゲインは <code>5 / d</code> です。左右の各チャンネルに同じ距離ゲインが掛かります。<a href="https://www.w3.org/TR/webaudio/#PannerNode" target="_blank" rel="noreferrer">W3C Web Audio APIのPannerNode</a></p><table tabindex="0"><thead><tr><th style="text-align:right;">正面を通る時刻からの差</th><th style="text-align:right;">音源の位置 <code>x</code></th><th style="text-align:right;">距離</th><th style="text-align:right;">予測周波数</th><th style="text-align:right;">距離ゲイン</th></tr></thead><tbody><tr><td style="text-align:right;">−0.5 秒</td><td style="text-align:right;">−20 m</td><td style="text-align:right;">22.36 m</td><td style="text-align:right;">491.24 Hz</td><td style="text-align:right;">0.224</td></tr><tr><td style="text-align:right;">0 秒</td><td style="text-align:right;">0 m</td><td style="text-align:right;">10 m</td><td style="text-align:right;">440.00 Hz</td><td style="text-align:right;">0.500</td></tr><tr><td style="text-align:right;">+0.5 秒</td><td style="text-align:right;">+20 m</td><td style="text-align:right;">22.36 m</td><td style="text-align:right;">398.44 Hz</td><td style="text-align:right;">0.224</td></tr></tbody></table><figure class="study-figure"><img src="'+i+'" alt="音源が40 m/sで最短距離10 mの直線を通過する。上のグラフでは周波数が接近中の高い値から正面の440 Hzを通り、通過後の低い値へ変わる。下のグラフでは距離ゲインが正面で最大の0.5になる。" width="760" height="416" loading="lazy"><figcaption>距離が同じ時刻では距離ゲインも同じです。聞き手に向かう速度は符号が変わるので、予測周波数は異なります。<a href="/study/images/browser/audio-flyby-curves.svg" target="_blank" rel="noopener noreferrer">周波数と距離ゲインの図を拡大</a></figcaption></figure><h2 id="音声と表示で同じ時刻を使う" tabindex="-1">音声と表示で同じ時刻を使う <a class="header-anchor" href="#音声と表示で同じ時刻を使う" aria-label="Permalink to &quot;音声と表示で同じ時刻を使う&quot;">​</a></h2><p>実践では正面を通る前後1秒ずつを、2秒の <code>OfflineAudioContext</code> に対応させます。音声の開始が <code>t = −1</code>、開始から1秒が <code>t = 0</code> です。位置は <code>PannerNode.positionX</code> に直線の動きとして予約し、再生速度は各時刻の軌道から計算した倍率の配列を <code>setValueCurveAtTime()</code> に渡します。配列内の値は指定した時間幅に配置され、間は補間されます。<code>playbackRate</code> は処理ブロックごとに値を読む k-rate のパラメーターです。<a href="https://www.w3.org/TR/webaudio/#dom-audioparam-setvaluecurveattime" target="_blank" rel="noreferrer">W3C Web Audio APIのsetValueCurveAtTime</a> · <a href="https://www.w3.org/TR/webaudio/#AudioBufferSourceNode" target="_blank" rel="noreferrer">AudioBufferSourceNode</a></p><p>実践では音源の速さと最短距離を選んで通過音を作ります。再生中の位置とグラフを見ながら、音が左から右へ移り、高さが変わる様子を聴けます。表示する予測値は各時刻の軌道から求めます。実測では各時刻を中心とする20 msの区間を使い、パンニング前の波形から周波数を、パンニング後の波形から左右の振幅を求めます。<a href="/study/practice/browser/audio-flyby-observation.html">通過音の実践</a></p>',16)])])}const f=t(s,[["render",l]]);export{b as __pageData,f as default};
